using System.Data;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Catalog;using Microsoft.Data.SqlClient;namespace MediDesk.Data.Repositories;public sealed class BackupRepository(SqlConnectionFactory f):IBackupRepository{public async Task<PagedResponse<BackupDto>>GetPageAsync(BackupQuery q,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("SELECT COUNT(1) FROM Backups WHERE IsDeleted=0;SELECT Id,BackupNumber,Type,SizeBytes,CreatedAtUtc,Status FROM Backups WHERE IsDeleted=0 ORDER BY CreatedAtUtc DESC OFFSET @O ROWS FETCH NEXT @P ROWS ONLY",c);cmd.Parameters.Add("@O",SqlDbType.Int).Value=(q.Page-1)*q.PageSize;cmd.Parameters.Add("@P",SqlDbType.Int).Value=q.PageSize;await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);var total=r.GetInt32(0);await r.NextResultAsync(ct);var a=new List<BackupDto>();while(await r.ReadAsync(ct))a.Add(new(r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetInt64(3),DateTime.SpecifyKind(r.GetDateTime(4),DateTimeKind.Utc),r.GetString(5)));return new(a,q.Page,q.PageSize,total);}public async Task<BackupDto>CreateAsync(string type,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("INSERT Backups(BackupNumber,Type,SizeBytes,Status,CreatedByUserId) OUTPUT INSERTED.Id,INSERTED.CreatedAtUtc VALUES(CONCAT('BKP-',YEAR(SYSUTCDATETIME()),'-',RIGHT('000000'+CAST(NEXT VALUE FOR dbo.BackupSequence AS VARCHAR(6)),6)),@T,0,'Completed',@U)",c);cmd.Parameters.Add("@T",SqlDbType.NVarChar,30).Value=type;cmd.Parameters.Add("@U",SqlDbType.BigInt).Value=u;await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return new(r.GetInt64(0),$"BKP-{DateTime.UtcNow.Year}",type,0,DateTime.SpecifyKind(r.GetDateTime(1),DateTimeKind.Utc),"Completed");}}

